parameters.jsCode:
// Two shapes come out of the Error Trigger: an execution that failed, and a
// trigger that could not start the workflow at all. The second has no
// execution, so reading d.execution.error would report "no message" for the
// failures that are hardest to notice.
const d = $input.first().json;
const triggerFailure = !!d.trigger;
const err = triggerFailure ? (d.trigger || {}).error : (d.execution || {}).error;

// Capped, and the stack left out. An error from an HTTP node routinely
// carries the request body, and here that body is a learner's message. A
// mail to an operator address is not the place for it; the execution in n8n
// is, and the mail says where to look.
const message = String((err || {}).message || 'no message reported').slice(0, 300);

return [{ json: {
  workflowName: (d.workflow || {}).name || 'unknown',
  workflowId:   (d.workflow || {}).id   || '-',
  kind:         triggerFailure ? 'trigger failed — the workflow never started'
                               : 'execution failed',
  node:         (d.execution || {}).lastNodeExecuted
                  || (((err || {}).node || {}).name) || 'unknown',
  message,
  executionId:  (d.execution || {}).id  || '-',
  executionUrl: (d.execution || {}).url || '',
  when:         new Date().toISOString(),
}}];

// ─── the shared alert state ──────────────────────────────────────────────────
// A mail per failure is a mail every five minutes for a workflow that runs
// every five minutes: 288 a day, and after the second day nobody reads any of
// them — including the one that matters. So a subject that is already known
// to be broken stays quiet for a while, and the next mail says how many
// failures it stands for.
//
// The state lives in Weaviate's WorkflowState under a fixed id, the same way
// chathistory-sync keeps its cursor. The status is read from the response
// rather than from a thrown error: a Code node runs in the task runner, and
// an exception loses its structured fields crossing that boundary, so a 404
// on the first run would arrive as an unexplained failure.
const QUIET_MINUTES = Number($env.ALERT_QUIET_MINUTES || 60);
const STATE_ID = 'a1e6d9c4-2f38-4b07-9c15-6de0f4a81b23';
const base = `http://smartrag-weaviate:${$env.WEAVIATE_HTTP_PORT || 8080}`;
const headers = {
  'Authorization': `Bearer ${$env.WEAVIATE_API_KEY}`,
  'Content-Type': 'application/json'
};

async function readState() {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: `${base}/v1/objects/WorkflowState/${STATE_ID}`,
    headers,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  if (res.statusCode === 404) return {};          // first run
  if (res.statusCode >= 400) {
    // Not fatal: an alert that cannot read its throttle should still be sent.
    console.log(`Alert state unreadable (HTTP ${res.statusCode}) — not throttling.`);
    return {};
  }
  const body = typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
  try {
    return JSON.parse(body?.properties?.value || '{}');
  } catch (e) {
    return {};
  }
}

async function writeState(state) {
  const payload = { properties: { key: 'alertState', value: JSON.stringify(state) } };
  const patched = await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${base}/v1/objects/WorkflowState/${STATE_ID}`,
    headers, body: payload,
    returnFullResponse: true, ignoreHttpStatusErrors: true,
  });
  if (patched.statusCode !== 404) return;
  // PATCH on something that does not exist is a 404, so the first run has to
  // create it — without this the state could never be written even once.
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${base}/v1/objects`,
    headers,
    body: { class: 'WorkflowState', id: STATE_ID, ...payload },
    returnFullResponse: true, ignoreHttpStatusErrors: true,
  });
}

const item = $input.first().json;
// Without a mail relay this whole path is decorative — and worse than
// decorative: the send would fail, the run would go red, and a red run is
// exactly what nobody looks at any more. So when SMTP_HOST is empty the
// report goes to the log instead and the execution stays green. The
// installer calls a relay strongly recommended for this reason among
// others; docs/requirements.md says how to set one up.
if (!($env.SMTP_HOST || '').trim()) {
  console.log('No SMTP relay configured (SMTP_HOST is empty), so this alert '
    + 'is logged instead of mailed:\n' + `${item.workflowName}: ${item.kind} at ${item.node} — ${item.message}`);
  return [];
}

const key = `error:${item.workflowId}`;
const state = await readState.call(this);
const now = Date.now();
const entry = state[key] || { last: 0, suppressed: 0 };
const minutesSince = (now - Number(entry.last || 0)) / 60000;

if (minutesSince < QUIET_MINUTES) {
  entry.suppressed = Number(entry.suppressed || 0) + 1;
  state[key] = entry;
  await writeState.call(this, state);
  console.log(`Suppressed: "${item.workflowName}" already reported ` +
              `${minutesSince.toFixed(0)} minute(s) ago (${entry.suppressed} since).`);
  return [];        // nothing downstream, so no mail
}

const alsoFailed = Number(entry.suppressed || 0);
state[key] = { last: now, suppressed: 0 };
await writeState.call(this, state);

return [{ json: { ...item, alsoFailed, quietMinutes: QUIET_MINUTES } }];

parameters.text:
=The workflow "{{ $json.workflowName }}" failed.

When:        {{ $json.when }}
What:        {{ $json.kind }}
Last node:   {{ $json.node }}
Message:     {{ $json.message }}

{{ $json.alsoFailed > 0 ? $json.alsoFailed + ' further failure(s) of this workflow were not mailed, to keep one broken job from filling the inbox.\n\n' : '' }}Execution:   {{ $json.executionUrl || $json.executionId }}
Workflow id: {{ $json.workflowId }}

The full error, with the data it was working on, is in the execution in n8n. It is deliberately not in this mail: an error from an HTTP node usually carries the request body, and here that is a learner's message.

Further failures of this workflow will stay quiet for {{ $json.quietMinutes }} minutes.
